#include <iostream>
#include <string>
#include <vector>

std::string solve(const std::vector<std::string>& grid, int r, int c, int size) {
    char first = grid[r][c];
    bool same = true;

    for (int i = r; i < r + size; ++i) {
        for (int j = c; j < c + size; ++j) {
            if (grid[i][j] != first) {
                same = false;
                break;
            }
        }
        if (!same) break;
    }

    if (same) {
        return std::string(1, first);
    }

    int half = size / 2;
    std::string tl = solve(grid, r, c, half);
    std::string tr = solve(grid, r, c + half, half);
    std::string bl = solve(grid, r + half, c, half);
    std::string br = solve(grid, r + half, c + half, half);

    return std::string("(") + tl + tr + bl + br + ")";
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    if (!(std::cin >> n)) {
        return 0;
    }

    std::vector<std::string> grid(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> grid[i];
    }

    std::string result = solve(grid, 0, 0, n);
    std::cout << result << '\n';

    return 0;
}
```

